#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

int main(void) {
    size_t length = 3, capacity = 3;
    int *items = NULL;
    if (capacity > SIZE_MAX / sizeof *items) return 1;
    items = malloc(capacity * sizeof *items);
    if (items == NULL) return 1;
    items[0] = 10; items[1] = 20; items[2] = 30;

    size_t new_capacity = 6;
    if (new_capacity > SIZE_MAX / sizeof *items) {
        free(items);
        return 1;
    }
    int *grown = realloc(items, new_capacity * sizeof *items);
    if (grown == NULL) {
        free(items);
        return 1;
    }
    items = grown;
    capacity = new_capacity;
    items[length++] = 40;
    printf("length=%zu capacity=%zu\n", length, capacity);
    for (size_t i = 0; i < length; ++i) printf("%d ", items[i]);
    puts("");
    free(items);
    items = NULL;
    return 0;
}
